/* Real estate playbook: urban renewal (פינוי-בינוי) patterns. Generated by scripts/playbook-check.mjs --write from supabase/playbooks/real_estate.json, do not edit by hand.
   Existing rules: only the pattern changes, and only where the live pattern still equals the one this was written against (a rule edited by hand since is left alone).
   New rules are inserted INACTIVE. A partner turns each on after reading its description and fallback clause.
   Hits on the labelled clauses in real_estate.cases.json: see the check script. Not applied to production until approved. */
update public.lalum_practice_playbooks set pattern = $pb$(לרשום|רישום|לרישום|תירשם|יירשם|תרשום|ירשום|נרשמה|תרשם)[^.\n]{0,80}הערת\s+אזהרה|הערת\s+אזהרה[^.\n]{0,80}(תירשם|יירשם|תרשום|תירשמנה|לטובת)$pb$, updated_at = now() where practice_area = $pb$REAL_ESTATE$pb$ and rule_name = $pb$הערת אזהרה לטובת הדיירים$pb$ and pattern = $pb$הערת\s+אזהרה$pb$;
update public.lalum_practice_playbooks set pattern = $pb$ערבות\s+(בנקאית|ביטוחית|אוטונומית|ביצוע|בנק)|ערבות\s+(לפי|על\s+פי|בהתאם\s+ל|כמשמעותה\s+ב)?\s*חוק\s+(ה)?מכר|חוק\s+(ה)?מכר\s*\(?דירות\)?|בטוחה\s+(לפי|על\s+פי)\s+חוק\s+(ה)?מכר$pb$, updated_at = now() where practice_area = $pb$REAL_ESTATE$pb$ and rule_name = $pb$ערבות להבטחת השקעת הדיירים$pb$ and pattern = $pb$ערבות\s+(בנקאית|ביטוחית|לפי\s+חוק\s+המכר|חוק\s+המכר)|חוק\s+המכר\s*\(דירות\)$pb$;
update public.lalum_practice_playbooks set pattern = $pb$(פיצוי|פיצויים)\s+(מוסכם|בגין\s+איחור|בשל\s+איחור|על\s+איחור)|(שכר\s+דירה|דמי\s+שכירות|שכירות)\s+חלופי(ת|ים)?|(שכר\s+דירה|דמי\s+שכירות)\s+(עבור|בעבור|בגין|בתקופת)\s+(ה)?(פינוי|בנייה|ביצוע|עבודות|תקופת)$pb$, updated_at = now() where practice_area = $pb$REAL_ESTATE$pb$ and rule_name = $pb$פיצוי בגין איחור במסירה ושכר דירה חלופי$pb$ and pattern = $pb$(פיצוי|פיצויים)\s+(מוסכם|בגין\s+איחור|בשל\s+איחור)|שכר\s+דירה|דמי\s+שכירות|שכירות\s+חלופית$pb$;
update public.lalum_practice_playbooks set pattern = $pb$ביטוח\s+(ה)?(קבלנים|עבודות|צד\s+ג|צד\s+שלישי|אחריות|כל\s+הסיכונים)|פוליסת\s+(ה)?ביטוח|פוליסות\s+(ה)?ביטוח$pb$, updated_at = now() where practice_area = $pb$REAL_ESTATE$pb$ and rule_name = $pb$ביטוח עבודות קבלניות וצד שלישי$pb$ and pattern = $pb$ביטוח\s+(קבלנים|עבודות\s+קבלניות|צד\s+ג|צד\s+שלישי)$pb$;
update public.lalum_practice_playbooks set pattern = $pb$מוותר(ים|ת)?\s+(בזאת\s+)?(לחלוטין\s+)?(וסופית\s+)?על\s+כל\s+(טענה|דרישה|זכות|תביעה)|לא\s+תהיה\s+ל\S+\s+(כל|שום)\s+(טענה|תביעה|דרישה)$pb$, updated_at = now() where practice_area = $pb$REAL_ESTATE$pb$ and rule_name = $pb$ויתור רחב על טענות$pb$ and pattern = $pb$מוותר(ים)?\s+(בזאת\s+)?(לחלוטין\s+)?על\s+כל\s+(טענה|דרישה|זכות)$pb$;
update public.lalum_practice_playbooks set pattern = $pb$מפרט\s+(ה)?(טכני|מכר|בנייה)|נספח\s+(ה)?(טכני|מפרט)$pb$, updated_at = now() where practice_area = $pb$REAL_ESTATE$pb$ and rule_name = $pb$מפרט טכני מחייב$pb$ and pattern = $pb$מפרט\s+(טכני|מכר)$pb$;
update public.lalum_practice_playbooks set pattern = $pb$שכר\s+טרחת?(ו)?\s+(של\s+)?(ה)?(עורך|עורכי)\s+(ה)?דין|שכר\s+טרחת?\s+עו"ד|שכ"ט\s+(ה)?(עו"ד|עורך)$pb$, updated_at = now() where practice_area = $pb$REAL_ESTATE$pb$ and rule_name = $pb$שכר טרחת עורך דין הדיירים$pb$ and pattern = $pb$שכר\s+טרחת?\s+(עורך\s+הדין|עורכי\s+הדין|עו"ד)$pb$;
insert into public.lalum_practice_playbooks (practice_area, rule_name, severity, description, fallback_clause, mode, pattern, source_citation, active) select $pb$REAL_ESTATE$pb$, $pb$רוב נדרש והסדר לדייר סרבן$pb$, $pb$YELLOW$pb$, $pb$לא נמצא הסדר לרוב ההסכמות הנדרש בבניין או לטיפול בדייר שאינו מסכים.$pb$, $pb$ההסכם מותנה בהשגת הסכמת [__]% מבעלי הדירות בבניין עד [תאריך]. חברת היזם תפעל מול דייר שלא הסכים על חשבונה ובאחריותה, ובלי לפגוע בזכויות הדיירים החותמים.$pb$, $pb$ABSENT$pb$, $pb$דייר(ים)?\s+סרב(ן|נ(ים|ית))|רוב\s+(נדרש|הדיירים|בעלי\s+הדירות)|אחוז(י)?\s+הסכמה|הסכמת\s+\S*\s*(מבעלי|מהדיירים)$pb$, $pb$פרקטיקה מקובלת בפרויקטי פינוי-בינוי. טעון אימות מול נוסח החוק לפני הפעלה.$pb$, false where not exists (select 1 from public.lalum_practice_playbooks where practice_area = $pb$REAL_ESTATE$pb$ and rule_name = $pb$רוב נדרש והסדר לדייר סרבן$pb$);
insert into public.lalum_practice_playbooks (practice_area, rule_name, severity, description, fallback_clause, mode, pattern, source_citation, active) select $pb$REAL_ESTATE$pb$, $pb$מועדי פינוי, בנייה ומסירה$pb$, $pb$RED$pb$, $pb$לא נמצאו מועדים מחייבים לפינוי, לסיום הבנייה ולמסירת הדירות החדשות.$pb$, $pb$היזם יפנה את הדירות לא לפני [תאריך], ישלים את הבנייה ויימסור לדיירים את הדירות החדשות עד [תאריך] ("המועד הקובע"). איחור מעבר ל-[__] ימים יזכה את הדיירים בפיצוי מוסכם כמפורט בהסכם.$pb$, $pb$ABSENT$pb$, $pb$(מועד|מועדי|תקופת)\s+(ה)?(פינוי|בנייה|מסירה|ביצוע)|(למסור|תימסר|יימסרו|תמסור|ימסור)\s+[^.\n]{0,60}עד\s+(ליום|לתאריך|ה)|לא\s+יאוחר\s+מ(יום|תאריך|ה)$pb$, $pb$פרקטיקה מקובלת בפרויקטי פינוי-בינוי.$pb$, false where not exists (select 1 from public.lalum_practice_playbooks where practice_area = $pb$REAL_ESTATE$pb$ and rule_name = $pb$מועדי פינוי, בנייה ומסירה$pb$);
insert into public.lalum_practice_playbooks (practice_area, rule_name, severity, description, fallback_clause, mode, pattern, source_citation, active) select $pb$REAL_ESTATE$pb$, $pb$דירה חלופית ותוספת שטח$pb$, $pb$YELLOW$pb$, $pb$לא נמצאה הגדרה של הדירה החלופית ושל תוספת השטח לדייר.$pb$, $pb$הדייר יקבל דירה חדשה בשטח של [__] מ"ר נטו, כולל מרפסת, חניה [__] ומחסן [__], בקומה ובכיוון כמפורט בנספח [__]. תוספת השטח היא בנוסף לשטח הדירה הקיימת.$pb$, $pb$ABSENT$pb$, $pb$דירה\s+חלופית|דירה\s+חדשה|תוספת\s+(שטח|מ"ר|בנייה)|מ"ר\s+(נטו|ברוטו)|שטח\s+הדירה\s+(החדשה|החלופית)$pb$, $pb$פרקטיקה מקובלת בפרויקטי פינוי-בינוי.$pb$, false where not exists (select 1 from public.lalum_practice_playbooks where practice_area = $pb$REAL_ESTATE$pb$ and rule_name = $pb$דירה חלופית ותוספת שטח$pb$);
insert into public.lalum_practice_playbooks (practice_area, rule_name, severity, description, fallback_clause, mode, pattern, source_citation, active) select $pb$REAL_ESTATE$pb$, $pb$מיסוי על הדייר$pb$, $pb$YELLOW$pb$, $pb$לא נמצא סעיף המסדיר את נשיאת מסי המקרקעין (שבח, רכישה, היטל השבחה) בעקבות העסקה.$pb$, $pb$כל מס, היטל או אגרה החלים בשל הפרויקט, למעט [__], יחולו על היזם. היזם יפעל לקבלת אישורי פטור או דחיית מס לדיירים ככל שניתן, ויישא בעלות הייעוץ המיסויי.$pb$, $pb$ABSENT$pb$, $pb$מס\s+(שבח|רכישה)|היטל\s+השבחה|פטור\s+(ממס|מתשלום)|מיסוי|מסי\s+מקרקעין$pb$, $pb$פרקטיקה מקובלת. הוראות מס מסוימות טעונות אימות מול נוסח החוק.$pb$, false where not exists (select 1 from public.lalum_practice_playbooks where practice_area = $pb$REAL_ESTATE$pb$ and rule_name = $pb$מיסוי על הדייר$pb$);
insert into public.lalum_practice_playbooks (practice_area, rule_name, severity, description, fallback_clause, mode, pattern, source_citation, active) select $pb$REAL_ESTATE$pb$, $pb$נציגות דיירים ומפקח$pb$, $pb$YELLOW$pb$, $pb$לא נמצאה נציגות דיירים או מפקח בנייה מטעם הדיירים.$pb$, $pb$הדיירים ימנו נציגות [ו/או מפקח בנייה מטעמם]. שכר המפקח והנציגות ישולמו על ידי היזם, והם יהיו רשאים לבקר את ביצוע הפרויקט בכל עת.$pb$, $pb$ABSENT$pb$, $pb$נציגות\s+(ה)?דיירים|מפקח\s+(בנייה\s+)?(מטעם|של)$pb$, $pb$פרקטיקה מקובלת בפרויקטי פינוי-בינוי.$pb$, false where not exists (select 1 from public.lalum_practice_playbooks where practice_area = $pb$REAL_ESTATE$pb$ and rule_name = $pb$נציגות דיירים ומפקח$pb$);
